private ComponentTemplateFinderInterface $templateFinder;

public function __construct(
    Environment|ComponentTemplateFinderInterface $templateFinder,
    private ServiceLocator $components,
    private PropertyAccessorInterface $propertyAccessor,
    private EventDispatcherInterface $eventDispatcher,
    private array $config,
    private array $classMap
) {
    $this->templateFinder = $templateFinder instanceof Environment ? new EnvironmentComponentTemplateFinder($templateFinder) : $templateFinder;
}

interface ComponentTemplateFinderInterface
{
    public function findAnonymousComponentTemplate(string $name): ?string;
}

final class EnvironmentComponentTemplateFinder implements ComponentTemplateFinderInterface
{
    public function __construct(private Environment $environment)
    {
    }

    public function findAnonymousComponentTemplate(string $name): ?string
    {
        $loader = $this->environment->getLoader();
        $componentPath = rtrim(str_replace(':', '/', $name));

        if ($loader->exists($componentPath)) {
            return $componentPath;
        }

        if ($loader->exists($componentPath.'.html.twig')) {
            return $componentPath.'.html.twig';
        }

        if ($loader->exists('components/'.$componentPath)) {
            return 'components/'.$componentPath;
        }

        if ($loader->exists('/components/'.$componentPath.'.html.twig')) {
            return '/components/'.$componentPath.'.html.twig';
        }

        return null;
    }
}

