58:             throw new \InvalidArgumentException(sprintf('Unknown component "%s". The registered components are: %s. And no template anonymous component founded', $name, implode(', ', array_keys($this->config))));
59:         }
60: 
61:         return new ComponentMetadata($config);
62:     }
63: 
64:     /**
65:      * Creates the component and "mounts" it with the passed data.
66:      */
67:     public function create(string $name, array $data = []): MountedComponent
68:     {
69:         return $this->mountFromObject(
70:             $this->getComponent($name),
71:             $data,
72:             $this->metadataFor($name)
73:         );
74:     }
75: 
76:     /**
77:      * @internal
78:      */
79:     public function mountFromObject(object $component, array $data, ComponentMetadata $componentMetadata): MountedComponent
80:     {
81:         $originalData = $data;
82:         $data = $this->preMount($component, $data);
83: 
84:         $this->mount($component, $data);
85: 
86:         // set data that wasn't set in mount on the component directly
87:         foreach ($data as $property => $value) {
88:             if ($this->propertyAccessor->isWritable($component, $property)) {
89:                 $this->propertyAccessor->setValue($component, $property, $value);
90: 
91:                 unset($data[$property]);
92:             }
93:         }
94: 
95:         $data = $this->postMount($component, $data);
96: 
97:         // create attributes from "attributes" key if exists
98:         $attributesVar = $componentMetadata->getAttributesVar();
99:         $attributes = $data[$attributesVar] ?? [];
100:         unset($data[$attributesVar]);
101: 
102:         // ensure remaining data is scalar
103:         foreach ($data as $key => $value) {
104:             if ($value instanceof \Stringable) {
105:                 $data[$key] = (string) $value;
106:                 continue;
107:             }
108: 
109:             if (!\is_scalar($value) && null !== $value) {
110:                 throw new \LogicException(sprintf('A "%s" prop was passed when creating the "%s" component. No matching %s property or mount() argument was found, so we attempted to use this as an HTML attribute. But, the value is not a scalar (it\'s a %s). Did you mean to pass this to your component or is there a typo on its name?', $key, $componentMetadata->getName(), $key, get_debug_type($value)));
111:             }
112:         }
113: 
114:         return new MountedComponent(
115:             $componentMetadata->getName(),
116:             $component,
117:             new ComponentAttributes(array_merge($attributes, $data)),
118:             $originalData
119:         );
120:     }
