122:     /**
123:      * Returns the "unmounted" component.
124:      */
125:     public function get(string $name): object
126:     {
127:         return $this->getComponent($name);
128:     }
129: 
130:     private function mount(object $component, array &$data): void
131:     {
132:         try {
133:             $method = (new \ReflectionClass($component))->getMethod('mount');
134:         } catch (\ReflectionException) {
135:             // no hydrate method
136:             return;
137:         }
138: 
139:         if ($component instanceof AnonymousComponent) {
140:             $component->mount($data);
141: 
142:             return;
143:         }
144: 
145:         $parameters = [];
146: 
147:         foreach ($method->getParameters() as $refParameter) {
148:             $name = $refParameter->getName();
149: 
150:             if (\array_key_exists($name, $data)) {
151:                 $parameters[] = $data[$name];
152: 
153:                 // remove the data element so it isn't used to set the property directly.
154:                 unset($data[$name]);
155:             } elseif ($refParameter->isDefaultValueAvailable()) {
156:                 $parameters[] = $refParameter->getDefaultValue();
157:             } else {
158:                 throw new \LogicException(sprintf('%s::mount() has a required $%s parameter. Make sure this is passed or make give a default value.', $component::class, $refParameter->getName()));
159:             }
160:         }
161: 
162:         $component->mount(...$parameters);
163:     }
164: 
165:     private function getComponent(string $name): object
166:     {
167:         $name = $this->classMap[$name] ?? $name;
168: 
169:         if (!$this->components->has($name)) {
170:             if ($this->isAnonymousComponent($name)) {
171:                 return new AnonymousComponent();
172:             }
173: 
174:             throw new \InvalidArgumentException(sprintf('Unknown component "%s". The registered components are: %s. And no anonymous component founded', $name, implode(', ', array_keys($this->components->getProvidedServices()))));
175:         }
176: 
177:         return $this->components->get($name);
178:     }
179: 
180:     private function preMount(object $component, array $data): array
181:     {
182:         $event = new PreMountEvent($component, $data);
183:         $this->eventDispatcher->dispatch($event);
184:         $data = $event->getData();
185: 
186:         foreach (AsTwigComponent::preMountMethods($component) as $method) {
187:             $newData = $component->{$method->name}($data);
188: 
189:             if (null !== $newData) {
190:                 $data = $newData;
191:             }
192:         }
193: 
194:         return $data;
195:     }
196: 
197:     private function postMount(object $component, array $data): array
198:     {
199:         $event = new PostMountEvent($component, $data);
200:         $this->eventDispatcher->dispatch($event);
201:         $data = $event->getData();
202: 
203:         foreach (AsTwigComponent::postMountMethods($component) as $method) {
204:             $newData = $component->{$method->name}($data);
205: 
206:             if (null !== $newData) {
207:                 $data = $newData;
208:             }
209:         }
210: 
211:         return $data;
212:     }
213: 
214:     private function isAnonymousComponent(string $name): bool
215:     {
216:         return null !== $this->findAnonymousComponentTemplate($name);
217:     }
218: 
219:     public function findAnonymousComponentTemplate(string $name): ?string
220:     {
221:         return $this->templateFinder->findAnonymousComponentTemplate($name);
222:     }
223: 
224:     /**
225:      * @return never
226:      */
227:     private function throwUnknownComponentException(string $name): void
228:     {
229:         throw new \InvalidArgumentException(sprintf('Unknown component "%s". The registered components are: %s', $name, implode(', ', array_keys($this->config))));
230:     }
231: }
232: 
233: interface ComponentTemplateFinderInterface
234: {
235:     public function findAnonymousComponentTemplate(string $name): ?string;
236: }
237: 
238: final class EnvironmentComponentTemplateFinder implements ComponentTemplateFinderInterface
239: {
240:     public function __construct(private Environment $environment)
241:     {
242:     }
243: 
244:     public function findAnonymousComponentTemplate(string $name): ?string
245:     {
246:         $loader = $this->environment->getLoader();
247:         $componentPath = rtrim(str_replace(':', '/', $name));
248: 
249:         if ($loader->exists($componentPath)) {
250:             return $componentPath;
251:         }
252: 
253:         if ($loader->exists($componentPath.'.html.twig')) {
254:             return $componentPath.'.html.twig';
255:         }
256: 
257:         if ($loader->exists('components/'.$componentPath)) {
258:             return 'components/'.$componentPath;
259:         }
260: 
261:         if ($loader->exists('/components/'.$componentPath.'.html.twig')) {
262:             return '/components/'.$componentPath.'.html.twig';
263:         }
264: 
265:         return null;
266:     }
267: }
